#!/usr/bin/env python3
"""Underline all headlines (all-caps section titles) in an unpacked docx.

Uses only the standard library (xml.dom.minidom). For each paragraph whose
text is entirely uppercase (with at least one letter), every run gets
<w:u w:val="single"/> inserted into its run properties in schema order.
"""
import sys
from pathlib import Path
from xml.dom import minidom

doc_path = Path(sys.argv[1]) / "word" / "document.xml"
W = "w:"

doc = minidom.parse(str(doc_path))


def paragraph_text(p):
    parts = []
    for t in p.getElementsByTagName(W + "t"):
        if t.firstChild and t.firstChild.nodeType == t.TEXT_NODE:
            parts.append(t.firstChild.data)
    return "".join(parts)


def set_underline(run):
    """Ensure the run's rPr contains <w:u w:val=\"single\"/> in schema order."""
    rPrs = [
        c
        for c in run.childNodes
        if c.nodeType == c.ELEMENT_NODE and c.tagName == W + "rPr"
    ]
    if rPrs:
        rPr = rPrs[0]
    else:
        rPr = doc.createElement(W + "rPr")
        run.insertBefore(rPr, run.firstChild)

    us = [
        c
        for c in rPr.childNodes
        if c.nodeType == c.ELEMENT_NODE and c.tagName == W + "u"
    ]
    if us:
        us[0].setAttribute(W + "val", "single")
        return False

    u = doc.createElement(W + "u")
    u.setAttribute(W + "val", "single")
    # CT_RPr order: ... szCs, highlight, u, effect, bdr, shd, fitText, vertAlign,
    # rtl, cs, em, lang, eastAsianLayout, specVanish, oMath
    after_u = {
        W + "effect", W + "bdr", W + "shd", W + "fitText", W + "vertAlign",
        W + "rtl", W + "cs", W + "em", W + "lang", W + "eastAsianLayout",
        W + "specVanish", W + "oMath",
    }
    children = [
        c for c in rPr.childNodes if c.nodeType == c.ELEMENT_NODE
    ]
    pos = len(children)
    for i, c in enumerate(children):
        if c.tagName in after_u:
            pos = i
            break
    if pos < len(children):
        rPr.insertBefore(u, children[pos])
    else:
        rPr.appendChild(u)
    return True


headlines = []
for p in doc.getElementsByTagName(W + "p"):
    text = paragraph_text(p).strip()
    if not text:
        continue
    if not text.isupper():
        continue
    if not any(ch.isalpha() for ch in text):
        continue
    changed = False
    for run in p.getElementsByTagName(W + "r"):
        set_underline(run)
        changed = True
    if changed:
        headlines.append(text)

data = doc.toxml(encoding="UTF-8")
decl_old = b'<?xml version="1.0" encoding="UTF-8"?>'
decl_new = b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
if data.startswith(decl_old):
    data = decl_new + data[len(decl_old):]
with open(doc_path, "wb") as f:
    f.write(data)

print(f"Underlined {len(headlines)} headlines:")
for h in headlines:
    print(" -", h)

